import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"未濟","description":"焦氏易林注 - 未濟","frontmatter":{"title":"未濟","description":"焦氏易林注 - 未濟"},"headers":[],"relativePath":"zh/classics/jiaoyilin/064.md","filePath":"zh/classics/jiaoyilin/064.md"}'),l={name:"zh/classics/jiaoyilin/064.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="未濟" tabindex="-1">未濟 <a class="header-anchor" href="#未濟" aria-label="Permalink to “未濟”">​</a></h1><h3 id="未濟-1" tabindex="-1">未濟 <a class="header-anchor" href="#未濟-1" aria-label="Permalink to “未濟”">​</a></h3><h3 id="未濟之乾" tabindex="-1">未濟之乾 <a class="header-anchor" href="#未濟之乾" aria-label="Permalink to “未濟之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>旦生夕死，名曰嬰鬼，不可得祀。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《升》。</p><h3 id="未濟之坤" tabindex="-1">未濟之坤 <a class="header-anchor" href="#未濟之坤" aria-label="Permalink to “未濟之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>大步上車，南到喜家。送我狐裘，與主俱來。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《困》。到，汲古作至，依宋本。</p><h3 id="未濟之屯" tabindex="-1">未濟之屯 <a class="header-anchor" href="#未濟之屯" aria-label="Permalink to “未濟之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>西多小星，三五在東。早夜晨興，勞苦無功。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《夬》。興，各本多作行，依《大過》之《夬》校。</p><h3 id="未濟之蒙" tabindex="-1">未濟之蒙 <a class="header-anchor" href="#未濟之蒙" aria-label="Permalink to “未濟之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>北陸藏冰，君子心悲。困於粒食，鬼驚我門。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坎為北陸，《左傳》日在北陸而藏冰。坎為冰，坤為藏。艮為君子，坎為心、為悲、為困。震為粒、為食，故曰困於粒食。坤為鬼、為門，震驚，故曰鬼驚我門。</p><h3 id="未濟之需" tabindex="-1">未濟之需 <a class="header-anchor" href="#未濟之需" aria-label="Permalink to “未濟之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>山水暴怒，壞梁折柱。稽難行旅，流連愁苦。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>詳《咸》之《豫》。</p><h3 id="未濟之訟" tabindex="-1">未濟之訟 <a class="header-anchor" href="#未濟之訟" aria-label="Permalink to “未濟之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>［原缺］。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>［原缺］</p><h3 id="未濟之師" tabindex="-1">未濟之師 <a class="header-anchor" href="#未濟之師" aria-label="Permalink to “未濟之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>狡兔趯趯，良犬逐咋。雄雌爰爰，為鷹所獲。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《益》。逐，元本作齚，依宋本、汲古。</p><h3 id="未濟之比" tabindex="-1">未濟之比 <a class="header-anchor" href="#未濟之比" aria-label="Permalink to “未濟之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>增祿益福，喜來入室，解除憂惑。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坎為室、為憂惑。陽居五，故吉。</p><h3 id="未濟之小畜" tabindex="-1">未濟之小畜 <a class="header-anchor" href="#未濟之小畜" aria-label="Permalink to “未濟之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>騎龍乘風，上見神公。彭祖受刺，王喬贊通。巫咸就位，拜福無窮。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《剝》。風，汲古作鳳，刺訛制，均依宋元本。</p><h3 id="未濟之履" tabindex="-1">未濟之履 <a class="header-anchor" href="#未濟之履" aria-label="Permalink to “未濟之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>天火卒起，燒我旁里。延及吾家，空盡己財。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。艮為天、為火，震起，故曰天火卒起。坤為里，艮為家，坤為財，坤虛，故空。</p><h3 id="未濟之泰" tabindex="-1">未濟之泰 <a class="header-anchor" href="#未濟之泰" aria-label="Permalink to “未濟之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>金帛黃寶，宜與我市。嫁娶有息，利得過倍。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>乾為金玉，坤為帛、為黃，故曰金帛黃寶。伏巽為市，震為嫁娶、為息。巽為利、為倍。○黃，宋元本作共，依汲古。過，汲古作萬，依宋元本。</p><h3 id="未濟之否" tabindex="-1">未濟之否 <a class="header-anchor" href="#未濟之否" aria-label="Permalink to “未濟之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>鬼魅之居，凶不可舍。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為鬼，艮為居、為舍，坤凶，故不可舍。</p><h3 id="未濟之同人" tabindex="-1">未濟之同人 <a class="header-anchor" href="#未濟之同人" aria-label="Permalink to “未濟之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>鳥飛兔走，各有畏惡。雕鷹為賊，亂我室舍。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。震為鳥、為飛、為兔、為走。坎為畏惡，艮為雕鷹，艮反與坎連，故曰雕鷹為賊。坤為亂，坎為室。○首句汲古作飛鳥逐兔，非，依宋元本。</p><h3 id="未濟之大有" tabindex="-1">未濟之大有 <a class="header-anchor" href="#未濟之大有" aria-label="Permalink to “未濟之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>初雖驚惶，後乃無傷，受其福慶。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>乾為福慶。</p><h3 id="未濟之謙" tabindex="-1">未濟之謙 <a class="header-anchor" href="#未濟之謙" aria-label="Permalink to “未濟之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>兩金相擊，勇氣均敵。日月鬬戰，不破不缺。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《噬嗑》。</p><h3 id="未濟之豫" tabindex="-1">未濟之豫 <a class="header-anchor" href="#未濟之豫" aria-label="Permalink to “未濟之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>曳綸河海，掛釣魴鯉。王孫利得，以享眾友。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>伏巽為綸，坤水坎水，故曰河海。坤為魚，故曰魴鯉。艮手，故曰掛釣魴鯉。艮為孫，震為王，坤為利，故曰王孫利得。坎為仲，艮為友。○得，宋元本作得［有誤］，依汲古。友，汲古作發，依宋元本。</p><h3 id="未濟之隨" tabindex="-1">未濟之隨 <a class="header-anchor" href="#未濟之隨" aria-label="Permalink to “未濟之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>犬畏狼虎，依人作輔。三夫執戟，伏不敢起，身安無咎。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為犬、為狼虎，震為人、為夫，數三，故曰三夫。艮為戟、為手，故曰執戟。巽為伏，艮為身。狼虎，汲古作虎狼，依宋元本。作，宋元本作有，依汲古。</p><h3 id="未濟之蠱" tabindex="-1">未濟之蠱 <a class="header-anchor" href="#未濟之蠱" aria-label="Permalink to “未濟之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>蜘蛛結網，以伺行旅。青蠅嚵聚，以求膏腴。觸我羅域，為網所得。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽為蜘蛛、為繩，故曰作網。震為行旅，艮止，故曰伺。巽為蠅，震為青，故曰青蠅。艮為求，震為觸。○第四句依宋元本，汲古無。</p><h3 id="未濟之臨" tabindex="-1">未濟之臨 <a class="header-anchor" href="#未濟之臨" aria-label="Permalink to “未濟之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>所望在外，鼎命方來。拭爵滌罍，炊食待之，不為季憂。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>伏艮為望。巽為命，震為鼎、為爵、為罍，按：《前漢賈誼傳》天子春秋鼎盛，註：鼎，方也。又《南史王僧辯傳》若鼎命中淪，請從此逝，又徐陵《為陳武帝與周宰相書》：欽若唐風，推其鼎命，又鼎貴、鼎臣、鼎族為古所常用，似有大意盛意。鼎命方來者，言大命方來也。伏艮為手，故曰拭、曰滌。兌為食，艮為季，坤為憂，震解，故曰不為季憂。○命，宋元本作金，滌訛條，均從汲古。</p><h3 id="未濟之觀" tabindex="-1">未濟之觀 <a class="header-anchor" href="#未濟之觀" aria-label="Permalink to “未濟之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>日月並居，常暗匪明。高山崩顛，丘陵為溪。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>詳《蹇》之《咸》。○溪，汲古作溪，依宋元本。</p><h3 id="未濟之噬嗑" tabindex="-1">未濟之噬嗑 <a class="header-anchor" href="#未濟之噬嗑" aria-label="Permalink to “未濟之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>春服既成，載華復生。莖葉盛茂，實穗泥泥。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>震為春、為服，艮為成，故曰春服既成。震為華、為生，震車，故曰載華復生。震為莖葉、為茂盛，艮為果蓏，故曰實穗。泥泥，盛茂。</p><h3 id="未濟之賁" tabindex="-1">未濟之賁 <a class="header-anchor" href="#未濟之賁" aria-label="Permalink to “未濟之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>華首山頭，仙道所游。利以居止，常無咎憂。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《頤》。</p><h3 id="未濟之剝" tabindex="-1">未濟之剝 <a class="header-anchor" href="#未濟之剝" aria-label="Permalink to “未濟之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>三狐嗥哭，自悲孤獨。野無所游，死於丘室。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為狐，數三，故曰三狐。震為歌，震反則哭，《易中孚六三》或泣或歌，即以艮為泣也，自覆象失傳，其辭遂不能解矣。坤寡，又一陽在上，皆孤獨之象也。坤為悲、為野、為死，艮為丘室，《禮》狐死正首丘，仁也。○嗥，宋元本作群，依汲古。游，汲古作由，依宋元本。</p><h3 id="未濟之復" tabindex="-1">未濟之復 <a class="header-anchor" href="#未濟之復" aria-label="Permalink to “未濟之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>火中暑退，禾黍其食。商人不至，市空無有。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>《月令》季夏之月，火昏中，《詩》七月流火，《傳》雲：火，大火也，流，下也。蓋火星未月昏中，申月西流，故謂之下。又《箋》雲火星中而寒暑退，暑退而禾稼熟，故曰禾黍其食。火中用未濟象。離居五中，故曰火中。離為暑，中則退矣。復下震為禾、為食、為商人，巽為市，巽伏，故市空。坤虛，故無有。○禾黍，汲古作求藿，依宋元本。</p><h3 id="未濟之無妄" tabindex="-1">未濟之無妄 <a class="header-anchor" href="#未濟之無妄" aria-label="Permalink to “未濟之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>獨立山巔，求麋耕田。草木不闢，秋飢無年。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>巽為寡，故曰獨立。艮為山、為求，震為麋、為耕。震為草木，伏兌為秋，無妄漢人多作無望，無望故無年，言麋非耕田之畜，故草木不闢也。○麋，宋本作鹿，依汲古。</p><h3 id="未濟之大畜" tabindex="-1">未濟之大畜 <a class="header-anchor" href="#未濟之大畜" aria-label="Permalink to “未濟之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>火雖熾，在吾後。寇雖近，在吾右。身安吉，不危殆。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>詳《歸妹》之《震》。三字句。</p><h3 id="未濟之頤" tabindex="-1">未濟之頤 <a class="header-anchor" href="#未濟之頤" aria-label="Permalink to “未濟之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>嚙嚙，貧鬼相責。無有歡怡，一日九結。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>詳《豐》之《晉》。</p><h3 id="未濟之大過" tabindex="-1">未濟之大過 <a class="header-anchor" href="#未濟之大過" aria-label="Permalink to “未濟之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>追亡逐北，至山而得。稚叔相呼，反其室廬。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>依《需》之《渙》校。各本皆作&quot;追亡逐北，呼還幼叔。至山而得，反歸其室&quot;，不協，惟《需》之《渙》是原詞，韻協象合。</p><h3 id="未濟之坎" tabindex="-1">未濟之坎 <a class="header-anchor" href="#未濟之坎" aria-label="Permalink to “未濟之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>銜命辱使，不堪厥事。遂墮落去，更為斯吏。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>伏巽為命，兌口，故曰銜命。震為使，伏巽為墮落，艮為僮僕，故曰斯吏。斯，賤役也。</p><h3 id="未濟之離" tabindex="-1">未濟之離 <a class="header-anchor" href="#未濟之離" aria-label="Permalink to “未濟之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>被珠函玉，沐浴仁德。應聘唐國，四門穆穆。蟊賊不作，凶惡伏慝。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>伏震為珠玉、為仁德，伏坎，故曰沐浴仁德。震為帝，故曰唐國。伏艮為國也。艮為門，震卦數四，故曰四門。本卦互巽為蟊賊，《詩小雅》及其蟊賊，《傳》食根曰蟊，食節曰賊。巽為伏匿。○函，汲古作銜，銜，兌象。函，伏艮象，茲從宋元本。</p><h3 id="未濟之咸" tabindex="-1">未濟之咸 <a class="header-anchor" href="#未濟之咸" aria-label="Permalink to “未濟之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>機關不便，不能出言。精誠適通，為人所冤。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>坎為機關，三上互大坎，故曰不便。震為言，震伏，故不能言。乾為精誠、為往，故曰精誠適通。適通，即感通也。乾為人，兌為言，正反兌，故曰為人所冤，言被誑也。易林每遇正反兌或正反震，不曰讒佞，即曰誣罔，皆本易與左氏。○第三句宋元本作精成通道，皆訛字，故依汲古。</p><h3 id="未濟之恒" tabindex="-1">未濟之恒 <a class="header-anchor" href="#未濟之恒" aria-label="Permalink to “未濟之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>瓮破缶缺，南行亡失。震為瓮、為缶，巽下斷，故破缺。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>震為南、為行，巽隕落，故曰亡失。○缶，宋元本作盆，依汲古。失，元本作夫，依宋本、汲古。</p><h3 id="未濟之遯" tabindex="-1">未濟之遯 <a class="header-anchor" href="#未濟之遯" aria-label="Permalink to “未濟之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>唇亡齒寒，積日凌根。朽不可用，為身災患。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>兌為唇齒，二四兌覆，故曰唇亡齒寒。乾為日，乾實，故曰積日。艮為根。凌，寒也，言日久根冷也。巽下斷，故曰朽。伏坤為身、為災患。○災，元本訛哭，依宋本、汲古。凌，疑訛。</p><h3 id="未濟之大壯" tabindex="-1">未濟之大壯 <a class="header-anchor" href="#未濟之大壯" aria-label="Permalink to “未濟之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>蒙惑憧憧，不知西東。魁罡指南，告我失中。利以宜止，去國憂患。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>通《觀》。坤迷，故曰蒙惑憧憧。本卦震為東，兌為西，惑故不知。艮為星，數七，故曰魁罡。《參同契》二月榆魁臨於卯，天罡據西，註：天罡即北斗。《夢溪筆談》鬥杓謂之剛，蓋前四星斗之魁，後三星斗之柄，故曰魁罡。震為南，伏艮為指，震言，故曰告。艮為止，坤為國、為憂患也。○失，局本訛室。</p><h3 id="未濟之晉" tabindex="-1">未濟之晉 <a class="header-anchor" href="#未濟之晉" aria-label="Permalink to “未濟之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>烏鴟摶翼，以避陰賊。盜伺二女，賴厥生福。旱災為疾，君無黍稷。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>艮為黔啄、為烏鴟。摶,束也，捲也。《考工記》鮑人捲而摶之是也。烏鴟摶翼者，言鳥下擊物時必戢其兩翼不開張，若捲束然，正以防不測也。震為翼，二四震覆，故曰摶翼。坎為盜賊、為隱伏，故曰以避陰賊。坤為女，數二，艮止，故曰伺二女。離火，艮火，故曰旱。震為君、為黍稷，震覆，故無黍稷。</p><h3 id="未濟之明夷" tabindex="-1">未濟之明夷 <a class="header-anchor" href="#未濟之明夷" aria-label="Permalink to “未濟之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>名成德就，項領不試。景公耄老，尼父逝去。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《剝》。</p><h3 id="未濟之家人" tabindex="-1">未濟之家人 <a class="header-anchor" href="#未濟之家人" aria-label="Permalink to “未濟之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>言與心詭，西行東坐。鯀湮洪水，佞賊為禍。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>離兩兌口相背，互坎為心，故曰言與心詭。坎為西，離為東，離為惡人，故曰鯀。坎為水、為賊，離兩兌口相對，故曰佞。明夷以離為有言，故此曰詭、曰佞。</p><h3 id="未濟之睽" tabindex="-1">未濟之睽 <a class="header-anchor" href="#未濟之睽" aria-label="Permalink to “未濟之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>獫狁匪度，治兵焦獲。伐鎬及方，與周爭強。元戎其駕，衰及夷王。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>《詩六月篇》獫狁匪茹，整居焦獲，註：焦獲，地名。坎為北，獫狁，北狄。離為甲兵，重離，故曰焦獲。鎬、方，皆地名。兌西象也。震為周，兌折震，故曰與周爭強。○焦，汲古作元，元作焦，今依宋元本。劉雲，毛詩作匪茹，箋雲，度也。鄭蓋用齊詩以申毛義。又雲：夷王雖亦命將出師，而未能攘逐，故曰衰。按：夷王始下堂，迎諸候，周室衰。</p><h3 id="未濟之蹇" tabindex="-1">未濟之蹇 <a class="header-anchor" href="#未濟之蹇" aria-label="Permalink to “未濟之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>三火起明，雨滅其光。高位疾顛，驕恣誅傷。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《師》。</p><h3 id="未濟之解" tabindex="-1">未濟之解 <a class="header-anchor" href="#未濟之解" aria-label="Permalink to “未濟之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>陰涿川決，水為吾祟。使我心憒，毋樹麻枲，居止凶殆。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>重坎，故曰陰涿川決。涿，《說文》流下滴也，《方言》瀧涿謂之沾。潰，言陰盛川決也。坎為祟、為心，震為麻枲，水多，故不可樹藝也。○首二句宋元本作承川決水、為吾之祟，茲依汲古。</p><h3 id="未濟之損" tabindex="-1">未濟之損 <a class="header-anchor" href="#未濟之損" aria-label="Permalink to “未濟之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>厭浥晨夜，道多湛露。瀸衣濡褲，重難以步。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《豫》。第三句宋本、汲古作沽我濡褲，依元本。</p><h3 id="未濟之益" tabindex="-1">未濟之益 <a class="header-anchor" href="#未濟之益" aria-label="Permalink to “未濟之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>宜行賈市，所求必倍。載喜抱子，與利為友。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《恆》。</p><h3 id="未濟之夬" tabindex="-1">未濟之夬 <a class="header-anchor" href="#未濟之夬" aria-label="Permalink to “未濟之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>陰變為陽，女化作男。治道得通，君臣相承。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《離》。</p><h3 id="未濟之姤" tabindex="-1">未濟之姤 <a class="header-anchor" href="#未濟之姤" aria-label="Permalink to “未濟之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>樹蔽牡荊，生●山旁。仇敵背憎，孰肯相迎。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>《本草》牡荊，一名黃荊，《淮南萬畢術》曰南山牡荊，指病自愈。巽為樹、為荊，震亦為荊，震伏，故牡荊不見。○牡，元本訛壯，孰訛熟，從宋本、汲古。</p><h3 id="未濟之萃" tabindex="-1">未濟之萃 <a class="header-anchor" href="#未濟之萃" aria-label="Permalink to “未濟之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>坐茵乘軒，據德宰臣。虞叔受命，六合和親。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>巽為茵，艮為坐，故曰坐茵。坤為車。軒，車也。坤為臣，伏震為帝，艮少，故曰虞叔。巽為命，坤為合，伏乾，數六，故曰六合。○據於德，見論語，汲古作握德，茲依宋元本。</p><h3 id="未濟之升" tabindex="-1">未濟之升 <a class="header-anchor" href="#未濟之升" aria-label="Permalink to “未濟之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>雲興蔽日，雨集草木，年茂歲熟。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為雲，乾為日，乾伏，故曰蔽日。兌為雨，巽為草木，故曰雨集草木。坤為年歲、為豐熟。○年茂，元本作茂年，非，今依宋本、汲古。</p><h3 id="未濟之困" tabindex="-1">未濟之困 <a class="header-anchor" href="#未濟之困" aria-label="Permalink to “未濟之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>播梅折枝，與母別離，絕不相知。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《旅》之《大過》。○播，宋本作蟠，依元本、汲古。播，種也。</p><h3 id="未濟之井" tabindex="-1">未濟之井 <a class="header-anchor" href="#未濟之井" aria-label="Permalink to “未濟之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>天旱水涸，枯槁無澤。困於沙石，未有所獲。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。艮為天、為火，故曰天旱水涸。坎上下皆火，故涸也。離為枯槁，艮為沙石。</p><h3 id="未濟之革" tabindex="-1">未濟之革 <a class="header-anchor" href="#未濟之革" aria-label="Permalink to “未濟之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>圭璧琮璜，執贄見王。百裡寧戚，應聘齊秦。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為玉、為王，坤為贄，艮手，故曰執贄。坤為里、為百、為憂，故曰百裡寧戚。本卦巽為齊，兌為秦，言百裡奚相秦，寧戚相齊也。</p><h3 id="未濟之鼎" tabindex="-1">未濟之鼎 <a class="header-anchor" href="#未濟之鼎" aria-label="Permalink to “未濟之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>龍渴求飲，黑雲景從。河伯捧醴，跪進酒漿，流潦滂滂。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震為龍，艮為求，坤為雲，坤黑，故曰黑雲景從。坤為河海，震為伯，坎為酒，艮手，故曰河伯奉醴。坤為漿，坎水，坤水，故曰流潦滂滂。○黑雲，汲古作雲黑，依宋元本。</p><h3 id="未濟之震" tabindex="-1">未濟之震 <a class="header-anchor" href="#未濟之震" aria-label="Permalink to “未濟之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>雹梅零墮，心思憒憒，亂我靈氣。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>首句依《大有》之《蒙》校。各本皆作零蒂。思，元本作積，依宋本、汲古。</p><h3 id="未濟之艮" tabindex="-1">未濟之艮 <a class="header-anchor" href="#未濟之艮" aria-label="Permalink to “未濟之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>鹿求其子，虎廬之里。唐伯李耳，貪不我許。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《隨》之《否》。</p><h3 id="未濟之漸" tabindex="-1">未濟之漸 <a class="header-anchor" href="#未濟之漸" aria-label="Permalink to “未濟之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>穿匏挹水，篝鐵然火。勞疲力竭，饑渴為禍。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>詳前《艮》之《坤》。</p><h3 id="未濟之歸妹" tabindex="-1">未濟之歸妹 <a class="header-anchor" href="#未濟之歸妹" aria-label="Permalink to “未濟之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>龍生馬淵，壽考且神。飛騰上天，舍宿軒轅，常居樂安。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為龍、為馬、為生，下兌，故曰淵。震為神，伏艮為壽、為天，震為飛騰，在艮上，故曰上天。坎為宿，艮為舍、為星，故曰軒轅。軒轅，星名也。震為樂，伏艮為安、為居。○第三句汲古無，依宋元本增。常居樂，汲古作居樂常，依宋元本。三四句指傅說騎箕事。</p><h3 id="未濟之豐" tabindex="-1">未濟之豐 <a class="header-anchor" href="#未濟之豐" aria-label="Permalink to “未濟之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>崔嵬北岳，天神貴客。溫仁正直，主布恩德。閔哀不已，蒙受大福。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《家人》。閔哀，依校，各本皆作衣冠，非。</p><h3 id="未濟之旅" tabindex="-1">未濟之旅 <a class="header-anchor" href="#未濟之旅" aria-label="Permalink to “未濟之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>鬼夜哭泣，齊失其國，為下所賊。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>二五互大坎為鬼、為夜，下卦震覆，故曰哭泣。本《中孚六三》爻詞也。巽為齊，艮為國，兌毀，坎失，故曰齊失其國。巽為盜賊。按：《戰國策》齊愍王時，有當闕而哭者，求之則不得，後果失國，為淖齒所殺。</p><h3 id="未濟之巽" tabindex="-1">未濟之巽 <a class="header-anchor" href="#未濟之巽" aria-label="Permalink to “未濟之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>二政多門，君失其權。三家專制，禍起季孫。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>伏震。互艮為門，初至四正反艮，故曰多門。震為君，巽為權，互坎，故曰失權。艮為家，震數三，故曰三家。艮為孫、為少，故曰季孫。季氏三家之一，曾逐昭公，故曰禍起季孫。</p><h3 id="未濟之兌" tabindex="-1">未濟之兌 <a class="header-anchor" href="#未濟之兌" aria-label="Permalink to “未濟之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>望幸不到，文章未就。王子逐兔，犬踦不得。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《渙》林。王，汲古作三，依宋元本。</p><h3 id="未濟之渙" tabindex="-1">未濟之渙 <a class="header-anchor" href="#未濟之渙" aria-label="Permalink to “未濟之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>伯虎仲熊，德義淵泓。使布五教，陰陽順序。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>元刊註高辛氏有伯虎、仲熊佐伯益治水。互艮為虎熊。震長，坎中，故曰伯虎仲熊。震為德，坎水，故曰德義淵泓。巽為命，卦數五，故曰五教。○淵泓，宋元本作昭明，茲依汲古。</p><h3 id="未濟之節" tabindex="-1">未濟之節 <a class="header-anchor" href="#未濟之節" aria-label="Permalink to “未濟之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>兩足四翼，飛入家國。寧我伯姊，與母相得。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《謙》。姊，宋元本作叔，依汲古。</p><h3 id="未濟之中孚" tabindex="-1">未濟之中孚 <a class="header-anchor" href="#未濟之中孚" aria-label="Permalink to “未濟之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>春秋禱祝，解禍除憂，君無災咎。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>互震為春，兌為秋、為禱祝、為君、為解。○祝，宋元本作祀，災咎作咎憂，均依汲古。</p><h3 id="未濟之小過" tabindex="-1">未濟之小過 <a class="header-anchor" href="#未濟之小過" aria-label="Permalink to “未濟之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>牧羊稻園，聞虎喧歡。畏懼悚息，終無禍患。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《隨》之《漸》。</p><h3 id="未濟之既濟" tabindex="-1">未濟之既濟 <a class="header-anchor" href="#未濟之既濟" aria-label="Permalink to “未濟之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>大蛇巨魚，相搏於郊。君臣隔塞，衛侯廬漕。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《訟》。第四句依校。各本皆作郭公出廬。</p><h3 id="未濟之未濟" tabindex="-1">未濟之未濟 <a class="header-anchor" href="#未濟之未濟" aria-label="Permalink to “未濟之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>志慢未習，單酒糗脯。數至神前，欲求所願，反得大患。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>坎為志、為酒。單，盡也，厚也。坎為糗脯，言厚備酒糗脯也。坎為願、為患。○志，宋元本作忠。願，宋本作顧，依汲古。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
